sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

  // フォームロード中でも「新規レコード」なら1回だけ実行したい
  // 既存レコードでは、値が変わったときのみ実行
  if (
    (isLoading && !g_form.isNewRecord()) || // 既存レコードのロード時は何もしない
    newValue === '' ||                      // 空なら何もしない
    newValue == oldValue                    // 値が変わっていなければ何もしない
  ) {
    return;
  }

  // GetEmailAddress Script Include を呼び出す
  var ga = new GlideAjax('GetEmailAddress');
  ga.addParam('sysparm_name', 'getEmail');
  ga.addParam('sysparm_userID', newValue); // Requested for の sys_id
  ga.getXML(populateEmailField);

  function populateEmailField(response) {
    var email =
      response.responseXML.documentElement.getAttribute('answer');

    // email が取れた場合のみセット
    if (email) {
      g_form.setValue('u_requested_for_email', email);
    }
  }
}
